	return false
}

func isGeneratedComment(comment string) bool {
	// Standard Go generated code pattern:
	// // Code generated .* DO NOT EDIT.
	return strings.HasPrefix(comment, "// Code generated ") && strings.HasSuffix(comment, " DO NOT EDIT.")
}

// getTypeName returns the type name suitable for exclude matching
func getTypeName(t types.Type) string {
	switch v := t.(type) {
	case *types.Named:
		obj := v.Obj()
		pkg := obj.Pkg()
		if pkg != nil {
			return pkg.Path() + "." + obj.Name()
		}
		return obj.Name()
	case *types.Pointer:
		return "*" + getTypeName(v.Elem())
	case *types.Interface:
		// For interfaces, use named type if possible
		return t.String()
	}
	return t.String()
}

// getReceiverTypeName gets the receiver type name for a method call
func getReceiverTypeName(t types.Type) string {
	switch v := t.(type) {
	case *types.Pointer:
		return "*" + getReceiverTypeName(v.Elem())
	case *types.Named:
		obj := v.Obj()
		pkg := obj.Pkg()
		if pkg != nil {
			return pkg.Path() + "." + obj.Name()
		}
		return obj.Name()
	case *types.Interface:
		// Use the string representation
		named, ok := t.(*types.Named)
		if ok {
			pkg := named.Obj().Pkg()
			if pkg != nil {
				return pkg.Path() + "." + named.Obj().Name()
			}
			return named.Obj().Name()
		}
		return t.String()
	}
	return t.String()
}

// funcInfo holds information about a function call for exclusion checking
type funcInfo struct {
	pkgPath  string // package path
	funcName string // function name
	recvType string // receiver type (empty for non-methods)
	isMethod bool
}

// getFuncInfo extracts function info from a call expression
func getFuncInfo(call *ast.CallExpr, info *types.Info) *funcInfo {
	fi := &funcInfo{}

	switch fn := call.Fun.(type) {
	case *ast.SelectorExpr:
		sel, ok := info.Selections[fn]
		if ok {
			// Method call
			fi.isMethod = true
			recv := sel.Recv()
			fi.recvType = getReceiverTypeName(recv)
			fi.funcName = fn.Sel.Name
			return fi
		}
		// Package-level function call
		obj := info.Uses[fn.Sel]
		if obj != nil {
			if pkg := obj.Pkg(); pkg != nil {
				fi.pkgPath = pkg.Path()
			}
			fi.funcName = fn.Sel.Name
		}
		return fi
	case *ast.Ident:
		obj := info.Uses[fn]
		if obj != nil {
			if pkg := obj.Pkg(); pkg != nil {
				fi.pkgPath = pkg.Path()
			}
			fi.funcName = fn.Name
		}
		return fi
	}
	return fi
}

// getVerboseFuncName returns the verbose function name for display
func getVerboseFuncName(call *ast.CallExpr, info *types.Info) string {
	switch fn := call.Fun.(type) {
	case *ast.SelectorExpr:
		sel, ok := info.Selections[fn]
		if ok {
			// Method call
			recv := sel.Recv()
			recvStr := getReceiverTypeName(recv)
			return "(" + recvStr + ")." + fn.Sel.Name
		}
		// Package function
		obj := info.Uses[fn.Sel]
		if obj != nil {
			if pkg := obj.Pkg(); pkg != nil {
				return pkg.Name() + "." + fn.Sel.Name
			}
		}
		return fn.Sel.Name
	}
	return ""
}

// isErrorType checks if a type implements the error interface
func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	// Check if it's the named "error" type
	if t.String() == "error" {
		return false // error interface itself - handled below
	}
	// Check if the type implements error interface
	errorIface := types.Universe.Lookup("error").Type().Underlying().(*types.Interface)
	return types.Implements(t, errorIface)
}

// isError checks if a type IS the error interface or implements it
func isError(t types.Type) bool {
	if t == nil {
		return false
	}
	named, ok := t.(*types.Named)
	if ok {
		if named.Obj().Name() == "error" && named.Obj().Pkg() == nil {
			return true // builtin error
		}
	}
	errorIface := types.Universe.Lookup("error").Type().Underlying().(*types.Interface)
	return types.Implements(t, errorIface)
}

// hasErrorReturn checks if a call expression returns at least one error
// Returns the indices of error return values
func getErrorReturnIndices(call *ast.CallExpr, info *types.Info) []int {
	t := info.TypeOf(call)
	if t == nil {
		return nil
	}

	// Check for tuple type (multiple returns)
	tuple, ok := t.(*types.Tuple)
	if ok {
		var indices []int
		for i := 0; i < tuple.Len(); i++ {
			if isError(tuple.At(i).Type()) {
				indices = append(indices, i)
			}
		}
		return indices
	}

	// Single return type
	if isError(t) {
		return []int{0}
	}
	return nil
}

// getFirstArgText returns the text of the first argument for exclude matching
func getFirstArgText(call *ast.CallExpr, info *types.Info, fset *token.FileSet, src []byte) string {
	if len(call.Args) == 0 {
		return ""
	}
	arg := call.Args[0]
	start := fset.File(arg.Pos()).Offset(arg.Pos())
	end := fset.File(arg.End()).Offset(arg.End())
	if start >= 0 && end <= len(src) && start <= end {
		return string(src[start:end])
	}
	return ""
}

// getFirstArgType returns the type of the first argument
func getFirstArgType(call *ast.CallExpr, info *types.Info) string {
	if len(call.Args) == 0 {
		return ""
	}
	t := info.TypeOf(call.Args[0])
	if t == nil {
		return ""
	}
	return getTypeName(t)
}

// matchesExclude checks if a function call matches an exclude entry
func matchesExclude(entry string, fi *funcInfo, call *ast.CallExpr, info *types.Info, fset *token.FileSet, src []byte) bool {
	ef := parseExcludeEntry(entry)
	if ef == nil {
		return false
	}

	if ef.isMethod {
		if !fi.isMethod {
			return false
		}
		if ef.funcName != fi.funcName {
			return false
		}
		// Match receiver type
		// ef.recv could be "hash.Hash" or "*bytes.Buffer" etc.
		recvType := fi.recvType
		// Normalize: remove import path prefix, keep just pkg.Type
		efRecv := ef.recv
		if matchesType(efRecv, recvType) {
			return matchesArgType(ef.argType, call, info, fset, src)
		}
		return false
	}

	// Package function
	if ef.pkg == "" {
		// No package specified - match by function name only
		if ef.funcName != fi.funcName {
			return false
		}
		return matchesArgType(ef.argType, call, info, fset, src)
	}

	// Match package + function name
	if ef.funcName != fi.funcName {
		return false
	}

	// Match package path
	if !matchesPkg(ef.pkg, fi.pkgPath) {
		return false
	}

	return matchesArgType(ef.argType, call, info, fset, src)
}

// matchesPkg checks if a package pattern matches a package path
func matchesPkg(pattern, pkgPath string) bool {
	if pattern == pkgPath {
		return true
	}
	// The pattern could be a short name like "os" matching "os"
	// or could be a full path like "crypto/rand" matching "crypto/rand"
	// Also handle vendored paths

	// Direct match
	if pattern == pkgPath {
		return true
	}

	// The pattern might be the last component
	parts := strings.Split(pkgPath, "/")
	if pattern == parts[len(parts)-1] {
		return true
	}

	// suffix match: pkgPath ends with /pattern
	if strings.HasSuffix(pkgPath, "/"+pattern) {
		return true
	}

	return false
}

// matchesType checks if a type pattern matches a receiver type
func matchesType(pattern, recvType string) bool {
	if pattern == recvType {
		return true
	}

	// Handle pointer types
	patternIsPtr := strings.HasPrefix(pattern, "*")
	recvIsPtr := strings.HasPrefix(recvType, "*")

	if patternIsPtr && recvIsPtr {
		return matchesType(pattern[1:], recvType[1:])
	}

	// Check with just the last package component
	// e.g. pattern "bytes.Buffer" should match "bytes.Buffer"
	// e.g. pattern "*bytes.Buffer" should match "*bytes.Buffer"

	// Strip pointer for both and compare the type names
	patternBase := strings.TrimPrefix(pattern, "*")
	recvBase := strings.TrimPrefix(recvType, "*")

	// Compare with package path normalization
	patternParts := strings.SplitN(patternBase, ".", 2)
	recvParts := strings.SplitN(recvBase, ".", 2)

	if len(patternParts) == 2 && len(recvParts) >= 1 {
		// pattern = "pkg.Type"
		// recv could be "full/path/pkg.Type"
		if strings.HasSuffix(recvBase, "."+patternParts[1]) || recvBase == patternBase {
			// Check package match
			recvPkgPath := strings.Join(recvParts[:len(recvParts)-1], ".")
			if patternIsPtr == recvIsPtr {
				_ = recvPkgPath
				return true
			}
		}
	}

	// Try suffix matching for full paths
	if strings.HasSuffix(recvBase, "/"+patternBase) {
		if patternIsPtr == recvIsPtr {
			return true
		}
	}

	return false
}

// matchesArgType checks if the argument type matches the exclude arg type
func matchesArgType(argTypePattern string, call *ast.CallExpr, info *types.Info, fset *token.FileSet, src []byte) bool {
	if argTypePattern == "" {
		return true
	}

	// Special cases: os.Stdout, os.Stderr
	if argTypePattern == "os.Stdout" || argTypePattern == "os.Stderr" {
		// Check if first arg is literally os.Stdout or os.Stderr
		if len(call.Args) > 0 {
			argText := getFirstArgText(call, info, fset, src)
			return argText == argTypePattern
		}
		return false
	}

	// Type match
	argType := getFirstArgType(call, info)
	return matchesType(argTypePattern, argType)
}

// shouldExclude checks if a function call should be excluded
func shouldExclude(excludes []string, fi *funcInfo, call *ast.CallExpr, info *types.Info, fset *token.FileSet, src []byte) bool {
	for _, entry := range excludes {
		if matchesExclude(entry, fi, call, info, fset, src) {
			return true
		}
	}
	return false
}

// shouldIgnore checks if a function should be ignored based on -ignore and -ignorepkg flags
func shouldIgnore(ignoreMap map[string]*regexp.Regexp, ignorePkgs []string, fi *funcInfo) bool {
	// Check ignorepkg first
	for _, pkg := range ignorePkgs {
		if fi.pkgPath == pkg || strings.HasSuffix(fi.pkgPath, "/"+pkg) {
			return true
		}
	}

	// Check ignore regex map
	for pkg, re := range ignoreMap {
		if pkg == "" || fi.pkgPath == pkg || strings.HasSuffix(fi.pkgPath, "/"+pkg) ||
			strings.HasSuffix(fi.pkgPath, "."+pkg) {
			if re.MatchString(fi.funcName) {
				return true
			}
		}
	}

	return false
}

// getLineText returns the source text from startPos to end of line
func getLineText(fset *token.FileSet, src []byte, startPos token.Pos) string {
	file := fset.File(startPos)
	if file == nil {
		return ""
	}
	offset := file.Offset(startPos)
	if offset < 0 || offset >= len(src) {
		return ""
	}
	// Find end of line
	end := offset
	for end < len(src) && src[end] != '\n' {
		end++
	}
	return string(src[offset:end])
}

// checkCall checks if a function call has an unchecked error
func (c *checker) checkCall(
	call *ast.CallExpr,
	stmt ast.Stmt,
	blankIdxs []int,
	info *types.Info,
	fset *token.FileSet,
	src []byte,
	fileInfo *token.File,
	verbose bool,
) {
	// Get error return indices
	errorIdxs := getErrorReturnIndices(call, info)
	if len(errorIdxs) == 0 {
		return
	}

	// Get function info for exclusion checking
	fi := getFuncInfo(call, info)

	// Check exclusions
	if shouldExclude(c.excludes, fi, call, info, fset, src) {
		return
	}

	// Check ignore map
	if shouldIgnore(c.cfg.ignoreMap, c.cfg.ignorePkgs, fi) {
		return
	}

	// Get verbose function name
	var fnName string
	if verbose {
		fnName = getVerboseFuncName(call, info)
	}

	switch s := stmt.(type) {
	case *ast.ExprStmt:
		// Unassigned call - always unchecked
		lparen := call.Lparen
		pos := fset.Position(lparen)
		startPos := call.Fun.Pos()
		line := getLineText(fset, src, startPos)
		c.errors = append(c.errors, uncheckedError{
			pos:  pos,
			line: line,
			fn:   fnName,
		})

	case *ast.AssignStmt:
		// Check which error returns are assigned to blank
		for _, errIdx := range errorIdxs {
			if errIdx >= len(s.Lhs) {
				continue
			}
			lhsIdent, ok := s.Lhs[errIdx].(*ast.Ident)
			if !ok {
				continue
			}
			if lhsIdent.Name != "_" {
				continue
			}
			// This error is assigned to blank
			if !c.cfg.blank {
				continue
			}
			pos := fset.Position(lhsIdent.Pos())
			startPos := s.Pos()
			line := getLineText(fset, src, startPos)
			c.errors = append(c.errors, uncheckedError{
				pos:  pos,
				line: line,
				fn:   fnName,
			})
		}

	case *ast.DeferStmt:
		// Deferred call - unchecked
		lparen := call.Lparen
		pos := fset.Position(lparen)
		startPos := s.Pos() // the 'defer' keyword
		line := getLineText(fset, src, startPos)
		c.errors = append(c.errors, uncheckedError{
			pos:  pos,
			line: line,
			fn:   fnName,
		})

	case *ast.GoStmt:
		// Go statement - unchecked
		lparen := call.Lparen
		pos := fset.Position(lparen)
		startPos := s.Pos() // the 'go' keyword
		line := getLineText(fset, src, startPos)
		c.errors = append(c.errors, uncheckedError{
			pos:  pos,
			line: line,
			fn:   fnName,
		})
	}
}

// checkTypeAssert checks a type assertion for unchecked errors
func (c *checker) checkTypeAssert(
	assert *ast.TypeAssertExpr,
	stmt ast.Stmt,
	info *types.Info,
	fset *token.FileSet,
	src []byte,
) {
	if !c.cfg.asserts {
		return
	}

	// Only single-value type assertions (not comma-ok)
	// If the assertion is in a 2-value assignment, it's OK
	if assign, ok := stmt.(*ast.AssignStmt); ok {
		if len(assign.Lhs) == 2 {
			// This is "v, ok := x.(T)" - comma-ok form, skip
			return
		}
	}

	// Report the assertion
	pos := fset.Position(assert.Pos())
	startPos := stmt.Pos()
	line := getLineText(fset, src, startPos)
	c.errors = append(c.errors, uncheckedError{
		pos:  pos,
		line: line,
		fn:   "",
	})
}

// walkFile walks an AST file checking for unchecked errors
func (c *checker) walkFile(file *ast.File, info *types.Info, fset *token.FileSet, src []byte) {
	ast.Inspect(file, func(n ast.Node) bool {
		if n == nil {
			return false
		}

		switch stmt := n.(type) {
		case *ast.ExprStmt:
			if call, ok := stmt.X.(*ast.CallExpr); ok {
				c.checkCall(call, stmt, nil, info, fset, src, fset.File(call.Pos()), c.cfg.verbose)
			}
			return false

		case *ast.AssignStmt:
			// Look for type assertions or blank error assignments
			for _, rhs := range stmt.Rhs {
				switch r := rhs.(type) {
				case *ast.CallExpr:
					// Check for blank error assignments
					c.checkCall(r, stmt, nil, info, fset, src, fset.File(r.Pos()), c.cfg.verbose)
				case *ast.TypeAssertExpr:
					c.checkTypeAssert(r, stmt, info, fset, src)
				}
			}
			return false

		case *ast.DeferStmt:
			if call, ok := stmt.Call.(*ast.CallExpr); ok {
				c.checkCall(call, stmt, nil, info, fset, src, fset.File(call.Pos()), c.cfg.verbose)
			}
			return false

		case *ast.GoStmt:
			if call, ok := stmt.Call.(*ast.CallExpr); ok {
				c.checkCall(call, stmt, nil, info, fset, src, fset.File(call.Pos()), c.cfg.verbose)
			}
			return false
		}

		return true
	})
}

// check runs errcheck on the given packages
func (c *checker) check(pkgs []*packages.Package) []uncheckedError {
	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 {
			continue
		}

		if c.cfg.verbose {
			fmt.Fprintf(os.Stderr, "checking %s\n", pkg.PkgPath)
		}

		for i, file := range pkg.Syntax {
			filename := fset.Position(file.Pos()).Filename

			// Skip test files if ignoretests is set
			if c.cfg.ignoretests && strings.HasSuffix(filename, "_test.go") {
				continue
			}

			// Skip generated files if ignoregenerated is set
			if c.cfg.ignoreGenerated && isGenerated(file) {
				continue
			}

			// Get source for this file
			src, err := getFileSource(filename, pkg.Fset, pkg.Syntax[i])
			if err != nil {
				continue
			}

			c.walkFile(file, pkg.TypesInfo, pkg.Fset, src)
		}
	}

	return c.errors
}

var fset *token.FileSet

// getFileSource reads the source bytes for a file
func getFileSource(filename string, fset *token.FileSet, file *ast.File) ([]byte, error) {
	src, err := os.ReadFile(filename)
	if err != nil {
		return nil, err
	}
	return src, nil
}

// ignoreValue is used for -ignore flag parsing
type ignoreValue struct {
	m map[string]*regexp.Regexp
}

func (v *ignoreValue) String() string {
	var parts []string
	for k, re := range v.m {
		if k == "" {
			parts = append(parts, re.String())
		} else {
			parts = append(parts, k+":"+re.String())
		}
	}
	return strings.Join(parts, ",")
}

func (v *ignoreValue) Set(s string) error {
	// Parse comma-separated list of pkg:regex pairs
	for _, pair := range strings.Split(s, ",") {
		pair = strings.TrimSpace(pair)
		if pair == "" {
			continue
		}
		colonIdx := strings.Index(pair, ":")
		if colonIdx < 0 {
			// No package specified - apply to all
			re, err := regexp.Compile(pair)
			if err != nil {
				return fmt.Errorf("invalid regex %q: %v", pair, err)
			}
			v.m[""] = re
		} else {
			pkg := pair[:colonIdx]
			pattern := pair[colonIdx+1:]
			re, err := regexp.Compile(pattern)
			if err != nil {
				return fmt.Errorf("invalid regex %q for package %q: %v", pattern, pkg, err)
			}
			v.m[pkg] = re
		}
	}
	return nil
}

// tagsValue is used for -tags flag parsing
type tagsValue struct {
	tags []string
}

func (v *tagsValue) String() string {
	return strings.Join(v.tags, " ")
}

func (v *tagsValue) Set(s string) error {
	// Split by comma or space
	for _, tag := range strings.FieldsFunc(s, func(r rune) bool {
		return r == ',' || r == ' '
	}) {
		v.tags = append(v.tags, tag)
	}
	return nil
}

func main() {
	// Parse flags
	abspath := flag.Bool("abspath", false, "print absolute paths to files")
	asserts := flag.Bool("asserts", false, "if true, check for ignored type assertion results")
	blank := flag.Bool("blank", false, "if true, check for errors assigned to blank identifier")
	excludeFile := flag.String("exclude", "", "Path to a file containing a list of functions to exclude from checking")
	excludeOnly := flag.Bool("excludeonly", false, "Use only excludes from -exclude file")
	ignoreVal := &ignoreValue{m: make(map[string]*regexp.Regexp)}
	flag.Var(ignoreVal, "ignore", "[deprecated] comma-separated list of pairs of the form pkg:regex\n            the regex is used to ignore names within pkg.")
	ignorePkg := flag.String("ignorepkg", "", "comma-separated list of package paths to ignore")
	ignoretests := flag.Bool("ignoretests", false, "if true, checking of _test.go files is disabled")
	ignoreGenerated := flag.Bool("ignoregenerated", false, "if true, checking of files with generated code is disabled")
	mod := flag.String("mod", "", "module download mode to use: readonly or vendor. See 'go help modules' for more.")
	tagsVal := &tagsValue{}
	flag.Var(tagsVal, "tags", "comma or space-separated list of build tags to include")
	verbose := flag.Bool("verbose", false, "produce more verbose logging")

	flag.Parse()

	patterns := flag.Args()
	if len(patterns) == 0 {
		flag.Usage()
		os.Exit(2)
	}

	// Build ignore map
	ignoreMap := ignoreVal.m

	// Set default fmt ignore if no explicit ignore for fmt
	if _, hasFmt := ignoreMap["fmt"]; !hasFmt && len(ignoreMap) == 0 {
		re, _ := regexp.Compile(".*")
		ignoreMap["fmt"] = re
	}

	// Parse ignorepkg
	var ignorePkgs []string
	if *ignorePkg != "" {
		for _, pkg := range strings.Split(*ignorePkg, ",") {
			pkg = strings.TrimSpace(pkg)
			if pkg != "" {
				ignorePkgs = append(ignorePkgs, pkg)
			}
		}
	}

	// Build exclude list
	var excludes []string
	if !*excludeOnly {
		excludes = append(excludes, builtinExcludes...)
	}

	if *excludeFile != "" {
		entries, err := loadExcludeFile(*excludeFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: failed to load exclude file: %v\n", err)
			os.Exit(2)
		}
		excludes = append(excludes, entries...)
	}

	cfg := &config{
		abspath:         *abspath,
		asserts:         *asserts,
		blank:           *blank,
		excludeFile:     *excludeFile,
		excludeOnly:     *excludeOnly,
		ignoreMap:       ignoreMap,
		ignorePkgs:      ignorePkgs,
		ignoretests:     *ignoretests,
		ignoreGenerated: *ignoreGenerated,
		mod:             *mod,
		tags:            tagsVal.tags,
		verbose:         *verbose,
		patterns:        patterns,
	}

	// Load packages
	loadCfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
			packages.NeedImports | packages.NeedTypes | packages.NeedTypesSizes |
			packages.NeedSyntax | packages.NeedTypesInfo | packages.NeedDeps,
		Tests: !*ignoretests,
		Fset:  token.NewFileSet(),
	}

	fset = loadCfg.Fset

	if len(tagsVal.tags) > 0 {
		loadCfg.BuildFlags = append(loadCfg.BuildFlags, "-tags="+strings.Join(tagsVal.tags, " "))
	}

	if *mod != "" {
		loadCfg.BuildFlags = append(loadCfg.BuildFlags, "-mod="+*mod)
	}

	pkgs, err := packages.Load(loadCfg, patterns...)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		os.Exit(2)
	}

	// Check for package loading errors
	var loadErrors []string
	for _, pkg := range pkgs {
		for _, e := range pkg.Errors {
			loadErrors = append(loadErrors, e.Msg)
		}
	}
	if len(loadErrors) > 0 {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: errors while loading package %s: [%s]\n",
			pkgs[0].PkgPath, strings.Join(loadErrors, " "))
		os.Exit(2)
	}

	// Run checks
	chkr := &checker{
		cfg:      cfg,
		excludes: excludes,
	}

	errors := chkr.check(pkgs)

	// Sort and deduplicate errors
	sort.Slice(errors, func(i, j int) bool {
		if errors[i].pos.Filename != errors[j].pos.Filename {
			return errors[i].pos.Filename < errors[j].pos.Filename
		}
		if errors[i].pos.Line != errors[j].pos.Line {
			return errors[i].pos.Line < errors[j].pos.Line
		}
		return errors[i].pos.Column < errors[j].pos.Column
	})

	// Print errors
	for _, e := range errors {
		filename := e.pos.Filename
		if !*abspath {
			// Make relative
			rel, err := filepath.Rel(".", filename)
			if err == nil {
				filename = rel
			}
		}

		if *verbose && e.fn != "" {
			fmt.Printf("%s:%d:%d:\t%s\t%s\n", filename, e.pos.Line, e.pos.Column, e.fn, e.line)
		} else {
			fmt.Printf("%s:%d:%d:\t%s\n", filename, e.pos.Line, e.pos.Column, e.line)
		}
	}

	if len(errors) > 0 {
		os.Exit(1)
	}
}
