// =============================================================================
// Exclude/Ignore Logic
// =============================================================================

// builtinExcludes is the default list of functions to exclude
var builtinExcludes = []string{
	"(hash.Hash).Write",
	"(*bytes.Buffer).Write",
	"(*bytes.Buffer).WriteByte",
	"(*bytes.Buffer).WriteRune",
	"(*bytes.Buffer).WriteString",
