	"(*strings.Builder).WriteByte",
	"(*strings.Builder).WriteRune",
	"(*strings.Builder).WriteString",
	"crypto/rand.Read",
	"math/rand.Read",
	"fmt.Print",
	"fmt.Printf",
	"fmt.Println",
	"fmt.Fprint(os.Stderr)",
	"fmt.Fprintf(os.Stderr)",
	"fmt.Fprintln(os.Stderr)",
}

// excludeEntry represents a parsed exclude list entry
type excludeEntry struct {
	isMethod bool
	recv     string // receiver type for methods (e.g. "*bytes.Buffer", "hash.Hash")
	pkg      string // package path for functions (e.g. "fmt", "crypto/rand")
	name     string // function/method name
	argType  string // optional first argument type filter
}

// parseExclude parses an exclude list entry
func parseExclude(entry string) *excludeEntry {
	entry = strings.TrimSpace(entry)
	if entry == "" || strings.HasPrefix(entry, "//") {
		return nil
	}

	e := &excludeEntry{}

	// Check for argument type suffix: FuncName(TYPE)
	if idx := strings.LastIndex(entry, "("); idx > 0 && strings.HasSuffix(entry, ")") {
		e.argType = entry[idx+1 : len(entry)-1]
		entry = entry[:idx]
	}

	// Check if it's a method: (RecvType).MethodName
	if strings.HasPrefix(entry, "(") {
		closeIdx := strings.Index(entry, ")")
		if closeIdx > 0 && closeIdx+1 < len(entry) && entry[closeIdx+1] == '.' {
			e.isMethod = true
			e.recv = entry[1:closeIdx]
			e.name = entry[closeIdx+2:]
			return e
		}
	}

	// Package function: [pkg.]FuncName
	lastDot := strings.LastIndex(entry, ".")
	if lastDot >= 0 {
		e.pkg = entry[:lastDot]
		e.name = entry[lastDot+1:]
	} else {
		e.name = entry
	}

	return e
}

// funcCallInfo holds info about a function call for matching
type funcCallInfo struct {
	isMethod bool
	recvType string // for methods: the receiver type string
	pkgPath  string // for package functions: import path
	pkgName  string // short package name
	name     string // function name
}

func (f *funcCallInfo) String() string {
	if f.isMethod {
		return "(" + f.recvType + ")." + f.name
	}
	return f.pkgName + "." + f.name
}

// matchRecvType checks if a receiver type matches a pattern
func matchRecvType(pattern, recvType string) bool {
	if pattern == recvType {
		return true
	}
	// Both might have pointers
	patPtr := strings.HasPrefix(pattern, "*")
	recvPtr := strings.HasPrefix(recvType, "*")

	patBase := strings.TrimPrefix(pattern, "*")
	recvBase := strings.TrimPrefix(recvType, "*")

	if patPtr != recvPtr {
		return false
	}

	// Try suffix match for package path
	// pattern "bytes.Buffer" should match "bytes.Buffer"
	// pattern "hash.Hash" should match "hash.Hash"
	if patBase == recvBase {
		return true
	}

	// Try matching with last path component
	// e.g. "bytes.Buffer" matches "bytes.Buffer"
	// Split by last '.'
	patDot := strings.LastIndex(patBase, ".")
	recvDot := strings.LastIndex(recvBase, ".")

	if patDot < 0 || recvDot < 0 {
		return false
	}

	patTypeName := patBase[patDot+1:]
	recvTypeName := recvBase[recvDot+1:]

	if patTypeName != recvTypeName {
		return false
	}

	patPkg := patBase[:patDot]
	recvPkg := recvBase[:recvDot]

	// recvPkg might be full import path, patPkg might be just the package name
	return recvPkg == patPkg || strings.HasSuffix(recvPkg, "/"+patPkg)
}

// matchPkg checks if a package path matches a pattern
func matchPkg(pattern, pkgPath string) bool {
	if pattern == pkgPath {
		return true
	}
	// Pattern might be just the last component
	if strings.HasSuffix(pkgPath, "/"+pattern) {
		return true
	}
	// Handle vendor paths
	if strings.Contains(pkgPath, "/vendor/") {
		vendorPart := pkgPath[strings.LastIndex(pkgPath, "/vendor/")+8:]
		if vendorPart == pattern || strings.HasSuffix(vendorPart, "/"+pattern) {
			return true
		}
	}
	return false
}

// shouldExclude checks if a function call matches any exclude entry
func shouldExclude(excludes []*excludeEntry, fi *funcCallInfo, call *ast.CallExpr, info *types.Info, fset *token.FileSet, src []byte) bool {
	for _, e := range excludes {
		if matchExclude(e, fi, call, info, fset, src) {
			return true
		}
	}
	return false
}

func matchExclude(e *excludeEntry, fi *funcCallInfo, call *ast.CallExpr, info *types.Info, fset *token.FileSet, src []byte) bool {
	if e.isMethod {
		if !fi.isMethod {
			return false
		}
		if e.name != fi.name {
			return false
		}
		if !matchRecvType(e.recv, fi.recvType) {
			return false
		}
	} else {
		if fi.isMethod {
			return false
		}
		if e.name != fi.name {
			return false
		}
		if e.pkg != "" && !matchPkg(e.pkg, fi.pkgPath) {
			return false
		}
	}

	// Check argument type filter
	if e.argType == "" {
		return true
	}

	// Special cases: os.Stdout, os.Stderr
	if e.argType == "os.Stdout" || e.argType == "os.Stderr" {
		if len(call.Args) == 0 {
			return false
		}
		argText := extractText(fset, src, call.Args[0].Pos(), call.Args[0].End())
		return argText == e.argType
	}

	// Type match
	if len(call.Args) == 0 {
		return false
	}
	argTypeStr := typeString(info.TypeOf(call.Args[0]))
	return matchRecvType(e.argType, argTypeStr)
}

// typeString converts a types.Type to a string for matching
func typeString(t types.Type) string {
	if t == nil {
		return ""
	}
	switch v := t.(type) {
	case *types.Pointer:
		return "*" + typeString(v.Elem())
	case *types.Named:
		obj := v.Obj()
		if obj.Pkg() != nil {
			return obj.Pkg().Path() + "." + obj.Name()
		}
		return obj.Name()
	default:
		return t.String()
	}
}

// shouldIgnore checks if a function should be ignored based on -ignore and -ignorepkg flags
func shouldIgnore(cfg *config, fi *funcCallInfo) bool {
	// Check ignorepkg
	for _, pkg := range cfg.ignorePkgs {
		if fi.pkgPath == pkg || strings.HasSuffix(fi.pkgPath, "/"+pkg) {
			return true
		}
	}

	// Check ignore regex map
	for pkg, re := range cfg.ignoreMap {
		var matches bool
		if pkg == "" {
			matches = true // apply to all packages
		} else {
			matches = (fi.pkgPath == pkg || strings.HasSuffix(fi.pkgPath, "/"+pkg))
		}
		if matches && re.MatchString(fi.name) {
			return true
		}
	}

	return false
}

// =============================================================================
// Package Loading
// =============================================================================

// goListPackage represents a package from 'go list -json'
type goListPackage struct {
	Dir          string
	ImportPath   string
	Name         string
	GoFiles      []string
	TestGoFiles  []string
	XTestGoFiles []string
	CgoFiles     []string
	Imports      []string
	TestImports  []string
	XTestImports []string
	Error        *struct{ Err string }
	DepsErrors   []*struct{ Err string }
	Match        []string
	ForTest      string   // the package being tested (for test variants)
}

// loadPackages runs 'go list' to get package information
func loadPackages(patterns []string, cfg *config) ([]*goListPackage, error) {
	args := []string{"list", "-json", "-e"}

	if len(cfg.tags) > 0 {
		args = append(args, "-tags="+strings.Join(cfg.tags, " "))
	}

	if cfg.mod != "" {
		args = append(args, "-mod="+cfg.mod)
	}

	// Add test flag
	args = append(args, "-test")

	args = append(args, "--")
	args = append(args, patterns...)

	cmd := exec.Command("go", args...)
	out, err := cmd.Output()
	if err != nil {
		// Check if it's an error with partial output
		if exitErr, ok := err.(*exec.ExitError); ok {
			if len(out) == 0 {
				return nil, fmt.Errorf("%s", exitErr.Stderr)
			}
		} else {
			return nil, err
		}
	}

	// Parse JSON output (multiple JSON objects)
	var pkgs []*goListPackage
	decoder := json.NewDecoder(strings.NewReader(string(out)))
	for decoder.More() {
		var p goListPackage
		if err := decoder.Decode(&p); err != nil {
			return nil, fmt.Errorf("parsing go list output: %v", err)
		}
		pkgs = append(pkgs, &p)
	}

	return pkgs, nil
}

// =============================================================================
// Type Checking
// =============================================================================

// checkedPackage holds a loaded and type-checked package
type checkedPackage struct {
	pkg   *goListPackage
	fset  *token.FileSet
	files []*ast.File
	info  *types.Info
	srcs  map[string][]byte // filename -> source bytes
}

// loadAndCheck loads and type-checks a package
func loadAndCheck(pkg *goListPackage, cfg *config, allPkgs map[string]*goListPackage) (*checkedPackage, error) {
	fset := token.NewFileSet()
	info := &types.Info{
		Types:      make(map[ast.Expr]types.TypeAndValue),
		Defs:       make(map[*ast.Ident]types.Object),
		Uses:       make(map[*ast.Ident]types.Object),
		Selections: make(map[*ast.SelectorExpr]*types.Selection),
		Implicits:  make(map[ast.Node]types.Object),
	}

	var files []*ast.File
	srcs := make(map[string][]byte)

	// Determine which files to parse
	var goFiles []string
	goFiles = append(goFiles, pkg.GoFiles...)
	if !cfg.ignoretests {
		goFiles = append(goFiles, pkg.TestGoFiles...)
	}

	for _, fname := range goFiles {
		fullPath := filepath.Join(pkg.Dir, fname)
		src, err := os.ReadFile(fullPath)
		if err != nil {
			return nil, fmt.Errorf("reading %s: %v", fullPath, err)
		}
		srcs[fullPath] = src
		f, err := parser.ParseFile(fset, fullPath, src, parser.ParseComments)
		if err != nil {
			return nil, fmt.Errorf("parsing %s: %v", fullPath, err)
		}
		files = append(files, f)
	}

	if len(files) == 0 {
		return &checkedPackage{pkg: pkg, fset: fset, files: files, info: info, srcs: srcs}, nil
	}

	conf := types.Config{
		Importer:                 importer.ForCompiler(fset, "gc", nil),
		IgnoreFuncBodies:         false,
		DisableUnusedImportCheck: true,
		Error: func(err error) {}, // ignore type errors
	}

	pkgName := pkg.ImportPath
	if pkg.ForTest != "" {
		pkgName = pkg.ForTest
	}

	_, err := conf.Check(pkgName, fset, files, info)
	_ = err // ignore errors - we might get partial results

	return &checkedPackage{
		pkg:   pkg,
		fset:  fset,
		files: files,
		info:  info,
		srcs:  srcs,
	}, nil
}

// =============================================================================
// Error Detection
// =============================================================================

// isErrorType checks if a type implements the error interface
func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}

	// Get the error interface from universe scope
	errorObj := types.Universe.Lookup("error")
	if errorObj == nil {
		return false
	}
	errorIface := errorObj.Type().Underlying().(*types.Interface)

	// Check if the named type is exactly 'error'
	if named, ok := t.(*types.Named); ok {
		if named.Obj().Name() == "error" && named.Obj().Pkg() == nil {
			return true
		}
	}

	// Check if pointer type
	if _, ok := t.(*types.Pointer); ok {
		return types.Implements(t, errorIface)
	}

	// Check if implements error
	return types.Implements(t, errorIface)
}

// getErrorIndices returns the indices of error return values in a call's return type
func getErrorIndices(call *ast.CallExpr, info *types.Info) []int {
	t := info.TypeOf(call)
	if t == nil {
		return nil
	}

	// Multiple returns
	if tuple, ok := t.(*types.Tuple); ok {
		var indices []int
		for i := 0; i < tuple.Len(); i++ {
			if isErrorType(tuple.At(i).Type()) {
				indices = append(indices, i)
			}
		}
		return indices
	}

	// Single return
	if isErrorType(t) {
		return []int{0}
	}

	return nil
}

// getFuncCallInfo extracts function call information for matching
func getFuncCallInfo(call *ast.CallExpr, info *types.Info) *funcCallInfo {
	fi := &funcCallInfo{}

	switch fn := call.Fun.(type) {
	case *ast.SelectorExpr:
		sel, ok := info.Selections[fn]
		if ok {
			// Method call
			fi.isMethod = true
			fi.name = fn.Sel.Name
			recv := sel.Recv()
			fi.recvType = typeString(recv)
			return fi
		}
		// Package function
		if obj := info.Uses[fn.Sel]; obj != nil {
			if pkg := obj.Pkg(); pkg != nil {
				fi.pkgPath = pkg.Path()
				fi.pkgName = pkg.Name()
			}
		}
		fi.name = fn.Sel.Name
		return fi

	case *ast.Ident:
		if obj := info.Uses[fn]; obj != nil {
			if pkg := obj.Pkg(); pkg != nil {
				fi.pkgPath = pkg.Path()
				fi.pkgName = pkg.Name()
			}
		}
		fi.name = fn.Name
		return fi
	}

	return fi
}

// getVerboseFuncName returns the verbose function name for display
func getVerboseFuncName(call *ast.CallExpr, info *types.Info) string {
	switch fn := call.Fun.(type) {
	case *ast.SelectorExpr:
		sel, ok := info.Selections[fn]
		if ok {
			// Method call
			recv := sel.Recv()
			recvStr := verboseTypeString(recv)
			return "(" + recvStr + ")." + fn.Sel.Name
		}
		// Package function
		if obj := info.Uses[fn.Sel]; obj != nil {
			if pkg := obj.Pkg(); pkg != nil {
				return pkg.Name() + "." + fn.Sel.Name
			}
		}
		return fn.Sel.Name
	}
	return ""
}

// verboseTypeString generates the verbose type string for method receiver display
func verboseTypeString(t types.Type) string {
	switch v := t.(type) {
	case *types.Pointer:
		return "*" + verboseTypeString(v.Elem())
	case *types.Named:
		obj := v.Obj()
		if obj.Pkg() != nil {
			return obj.Pkg().Path() + "." + obj.Name()
		}
		return obj.Name()
	case *types.Interface:
		// For interfaces, check if it's a named interface
		if named, ok := t.(*types.Named); ok {
			obj := named.Obj()
			if obj.Pkg() != nil {
				return obj.Pkg().Path() + "." + obj.Name()
			}
			return obj.Name()
		}
		return t.String()
	default:
		return t.String()
	}
}

// =============================================================================
// Source Text Extraction
// =============================================================================

// extractText returns the source text from startPos to endPos
func extractText(fset *token.FileSet, src []byte, startPos, endPos token.Pos) string {
	file := fset.File(startPos)
	if file == nil {
		return ""
	}
	start := file.Offset(startPos)
	end := file.Offset(endPos)
	if start < 0 || end > len(src) || start > end {
		return ""
	}
	return string(src[start:end])
}

// getLineText returns the source text from startPos to end of line
func getLineText(fset *token.FileSet, src []byte, startPos token.Pos) string {
	file := fset.File(startPos)
	if file == nil {
		return ""
	}
	offset := file.Offset(startPos)
	if offset < 0 || offset >= len(src) {
		return ""
	}
	end := offset
	for end < len(src) && src[end] != '\n' {
		end++
	}
	return string(src[offset:end])
}

// =============================================================================
// Generated Code Detection
// =============================================================================

// isGeneratedFile checks if a file is generated code
func isGeneratedFile(file *ast.File) bool {
	for _, cg := range file.Comments {
		for _, c := range cg.List {
			if isGeneratedComment(c.Text) {
				return true
			}
		}
	}
	return false
}

// isGeneratedComment checks if a comment indicates generated code
func isGeneratedComment(comment string) bool {
	// Standard Go generated code pattern: // Code generated .* DO NOT EDIT.
	return strings.HasPrefix(comment, "// Code generated ") &&
		strings.HasSuffix(comment, " DO NOT EDIT.")
}

// =============================================================================
// Main Checker Logic
// =============================================================================

// checker holds the state for an errcheck run
type checker struct {
	cfg      *config
	excludes []*excludeEntry
	seen     map[string]bool // for deduplication: "filename:line:col" -> true
}

// checkPackage checks a single package for unchecked errors
func (c *checker) checkPackage(cp *checkedPackage) []uncheckedError {
	var errors []uncheckedError

	for _, file := range cp.files {
		filename := cp.fset.Position(file.Pos()).Filename

		// Skip test files if -ignoretests is set
		if c.cfg.ignoretests && strings.HasSuffix(filename, "_test.go") {
			continue
		}

		// Skip generated files if -ignoregenerated is set
		if c.cfg.ignoreGenerated && isGeneratedFile(file) {
			continue
		}

		src := cp.srcs[filename]
		if src == nil {
			var err error
			src, err = os.ReadFile(filename)
			if err != nil {
				continue
			}
		}

		fileErrors := c.walkFile(file, cp.info, cp.fset, src)
		errors = append(errors, fileErrors...)
	}

	return errors
}

// walkFile walks an AST file checking for unchecked errors
func (c *checker) walkFile(file *ast.File, info *types.Info, fset *token.FileSet, src []byte) []uncheckedError {
	var errors []uncheckedError

	ast.Inspect(file, func(n ast.Node) bool {
		if n == nil {
			return false
		}

		switch stmt := n.(type) {
		case *ast.ExprStmt:
			if call, ok := stmt.X.(*ast.CallExpr); ok {
				errs := c.checkCall(call, stmt, info, fset, src)
				errors = append(errors, errs...)
			}
			return false

		case *ast.AssignStmt:
			for _, rhs := range stmt.Rhs {
				switch r := rhs.(type) {
				case *ast.CallExpr:
					errs := c.checkCallAssign(r, stmt, info, fset, src)
					errors = append(errors, errs...)
				case *ast.TypeAssertExpr:
					if e := c.checkTypeAssert(r, stmt, info, fset, src); e != nil {
						errors = append(errors, *e)
					}
				}
			}
			return false

		case *ast.DeferStmt:
			if call, ok := stmt.Call.(*ast.CallExpr); ok {
				errs := c.checkCallDefer(call, stmt, info, fset, src)
				errors = append(errors, errs...)
			}
			return false

		case *ast.GoStmt:
			if call, ok := stmt.Call.(*ast.CallExpr); ok {
				errs := c.checkCallGo(call, stmt, info, fset, src)
				errors = append(errors, errs...)
			}
			return false
		}

		return true
	})

	return errors
}

// checkCall checks an unassigned function call
func (c *checker) checkCall(call *ast.CallExpr, stmt *ast.ExprStmt, info *types.Info, fset *token.FileSet, src []byte) []uncheckedError {
	errorIdxs := getErrorIndices(call, info)
	if len(errorIdxs) == 0 {
		return nil
	}

	fi := getFuncCallInfo(call, info)
	if shouldExclude(c.excludes, fi, call, info, fset, src) {
		return nil
	}
	if shouldIgnore(c.cfg, fi) {
		return nil
	}

	pos := fset.Position(call.Lparen)
	line := getLineText(fset, src, call.Fun.Pos())
	fn := ""
	if c.cfg.verbose {
		fn = getVerboseFuncName(call, info)
	}

	return []uncheckedError{{pos: pos, line: line, fn: fn}}
}

// checkCallAssign checks a function call in an assignment statement
func (c *checker) checkCallAssign(call *ast.CallExpr, stmt *ast.AssignStmt, info *types.Info, fset *token.FileSet, src []byte) []uncheckedError {
	errorIdxs := getErrorIndices(call, info)
	if len(errorIdxs) == 0 {
		return nil
	}

	// Check if any error index has a blank assignment
	var blankErrorIdxs []int
	for _, idx := range errorIdxs {
		if idx >= len(stmt.Lhs) {
			continue
		}
		ident, ok := stmt.Lhs[idx].(*ast.Ident)
		if ok && ident.Name == "_" {
			blankErrorIdxs = append(blankErrorIdxs, idx)
		}
	}

	if len(blankErrorIdxs) == 0 {
		return nil
	}

	if !c.cfg.blank {
		return nil
	}

	fi := getFuncCallInfo(call, info)
	if shouldExclude(c.excludes, fi, call, info, fset, src) {
		return nil
	}
	if shouldIgnore(c.cfg, fi) {
		return nil
	}

	fn := ""
	if c.cfg.verbose {
		fn = getVerboseFuncName(call, info)
	}

	var errors []uncheckedError
	for _, idx := range blankErrorIdxs {
		lhsIdent := stmt.Lhs[idx].(*ast.Ident)
		pos := fset.Position(lhsIdent.Pos())
		line := getLineText(fset, src, stmt.Pos())
		errors = append(errors, uncheckedError{pos: pos, line: line, fn: fn})
	}

	return errors
}

// checkCallDefer checks a deferred function call
func (c *checker) checkCallDefer(call *ast.CallExpr, stmt *ast.DeferStmt, info *types.Info, fset *token.FileSet, src []byte) []uncheckedError {
	errorIdxs := getErrorIndices(call, info)
	if len(errorIdxs) == 0 {
		return nil
	}

	fi := getFuncCallInfo(call, info)
	if shouldExclude(c.excludes, fi, call, info, fset, src) {
		return nil
	}
	if shouldIgnore(c.cfg, fi) {
		return nil
	}

	pos := fset.Position(call.Lparen)
	line := getLineText(fset, src, stmt.Pos())
	fn := ""
	if c.cfg.verbose {
		fn = getVerboseFuncName(call, info)
	}

	return []uncheckedError{{pos: pos, line: line, fn: fn}}
}

// checkCallGo checks a goroutine function call
func (c *checker) checkCallGo(call *ast.CallExpr, stmt *ast.GoStmt, info *types.Info, fset *token.FileSet, src []byte) []uncheckedError {
	errorIdxs := getErrorIndices(call, info)
	if len(errorIdxs) == 0 {
		return nil
	}

	fi := getFuncCallInfo(call, info)
	if shouldExclude(c.excludes, fi, call, info, fset, src) {
		return nil
	}
	if shouldIgnore(c.cfg, fi) {
		return nil
	}

	pos := fset.Position(call.Lparen)
	line := getLineText(fset, src, stmt.Pos())
	fn := ""
	if c.cfg.verbose {
		fn = getVerboseFuncName(call, info)
	}

	return []uncheckedError{{pos: pos, line: line, fn: fn}}
}

// checkTypeAssert checks a type assertion for unchecked errors
func (c *checker) checkTypeAssert(assert *ast.TypeAssertExpr, stmt *ast.AssignStmt, info *types.Info, fset *token.FileSet, src []byte) *uncheckedError {
	if !c.cfg.asserts {
		return nil
	}

	// Only single-value type assertions (not comma-ok)
	if len(stmt.Lhs) == 2 {
		return nil
	}

	pos := fset.Position(assert.Pos())
	line := getLineText(fset, src, stmt.Pos())

	return &uncheckedError{pos: pos, line: line, fn: ""}
}

// =============================================================================
// Flag Parsing Helpers
// =============================================================================

// ignoreFlag implements flag.Value for -ignore
type ignoreFlag struct {
	m       map[string]*regexp.Regexp
	changed bool
}

func (f *ignoreFlag) String() string {
	var parts []string
	for k, re := range f.m {
		if k == "" {
			parts = append(parts, re.String())
		} else {
			parts = append(parts, k+":"+re.String())
		}
	}
	return strings.Join(parts, ",")
}

func (f *ignoreFlag) Set(s string) error {
	f.changed = true
	for _, pair := range strings.Split(s, ",") {
		pair = strings.TrimSpace(pair)
		if pair == "" {
			continue
		}
		colonIdx := strings.Index(pair, ":")
		if colonIdx < 0 {
			re, err := regexp.Compile(pair)
			if err != nil {
				return fmt.Errorf("invalid regex %q: %v", pair, err)
			}
			f.m[""] = re
		} else {
			pkg := pair[:colonIdx]
			pattern := pair[colonIdx+1:]
			re, err := regexp.Compile(pattern)
			if err != nil {
				return fmt.Errorf("invalid regex %q for package %q: %v", pattern, pkg, err)
			}
			f.m[pkg] = re
		}
	}
	return nil
}

// tagsFlag implements flag.Value for -tags
type tagsFlag struct {
	tags []string
}

func (f *tagsFlag) String() string {
	return strings.Join(f.tags, " ")
}

func (f *tagsFlag) Set(s string) error {
	for _, tag := range strings.FieldsFunc(s, func(r rune) bool {
		return r == ',' || r == ' '
	}) {
		if tag != "" {
			f.tags = append(f.tags, tag)
		}
	}
	return nil
}

// loadExcludeFile loads exclude entries from a file
func loadExcludeFile(path string) ([]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var entries []string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line != "" && !strings.HasPrefix(line, "//") {
			entries = append(entries, line)
		}
	}
	return entries, scanner.Err()
}

// =============================================================================
// Main
// =============================================================================

func main() {
	// Define flags
	abspath := flag.Bool("abspath", false, "print absolute paths to files")
	asserts := flag.Bool("asserts", false, "if true, check for ignored type assertion results")
	blank := flag.Bool("blank", false, "if true, check for errors assigned to blank identifier")
	excludeFile := flag.String("exclude", "", "Path to a file containing a list of functions to exclude from checking")
	excludeOnly := flag.Bool("excludeonly", false, "Use only excludes from -exclude file")
	ignoreVal := &ignoreFlag{m: make(map[string]*regexp.Regexp)}
	flag.Var(ignoreVal, "ignore", "[deprecated] comma-separated list of pairs of the form pkg:regex\n            the regex is used to ignore names within pkg.")
	ignorePkg := flag.String("ignorepkg", "", "comma-separated list of package paths to ignore")
	ignoretests := flag.Bool("ignoretests", false, "if true, checking of _test.go files is disabled")
	ignoreGenerated := flag.Bool("ignoregenerated", false, "if true, checking of files with generated code is disabled")
	mod := flag.String("mod", "", "module download mode to use: readonly or vendor. See 'go help modules' for more.")
	tagsVal := &tagsFlag{}
	flag.Var(tagsVal, "tags", "comma or space-separated list of build tags to include")
	verbose := flag.Bool("verbose", false, "produce more verbose logging")

	flag.Parse()

	patterns := flag.Args()
	if len(patterns) == 0 {
		flag.Usage()
		os.Exit(2)
	}

	// Build ignore map
	ignoreMap := ignoreVal.m

	// Apply default: fmt package is ignored by default unless explicitly overridden
	if !ignoreVal.changed {
		re, _ := regexp.Compile(".*")
		ignoreMap["fmt"] = re
	}

	// Parse ignorepkg list
	var ignorePkgs []string
	for _, pkg := range strings.Split(*ignorePkg, ",") {
		if pkg := strings.TrimSpace(pkg); pkg != "" {
			ignorePkgs = append(ignorePkgs, pkg)
		}
	}

	// ignorepkg overrides ignore for the same package
	for _, pkg := range ignorePkgs {
		delete(ignoreMap, pkg)
	}

	cfg := &config{
		abspath:         *abspath,
		asserts:         *asserts,
		blank:           *blank,
		excludeFile:     *excludeFile,
		excludeOnly:     *excludeOnly,
		ignoreMap:       ignoreMap,
		ignorePkgs:      ignorePkgs,
		ignoretests:     *ignoretests,
		ignoreGenerated: *ignoreGenerated,
		mod:             *mod,
		tags:            tagsVal.tags,
		verbose:         *verbose,
	}

	// Build exclude list
	var excludeStrs []string
	if !*excludeOnly {
		excludeStrs = append(excludeStrs, builtinExcludes...)
	}

	if *excludeFile != "" {
		entries, err := loadExcludeFile(*excludeFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error reading exclude file: %v\n", err)
			os.Exit(2)
		}
		excludeStrs = append(excludeStrs, entries...)
	}

	var excludes []*excludeEntry
	for _, s := range excludeStrs {
		if e := parseExclude(s); e != nil {
			excludes = append(excludes, e)
		}
	}

	// Load packages using 'go list'
	pkgList, err := loadPackages(patterns, cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		os.Exit(2)
	}

	// Check for loading errors
	for _, pkg := range pkgList {
		if pkg.Error != nil {
			fmt.Fprintf(os.Stderr, "error: failed to check packages: errors while loading package %s: [%s]\n",
				pkg.ImportPath, pkg.Error.Err)
			os.Exit(2)
		}
	}

	// Create checker
	chkr := &checker{
		cfg:      cfg,
		excludes: excludes,
		seen:     make(map[string]bool),
	}

	// All errors found
	var allErrors []uncheckedError
	seenPos := make(map[string]bool)

	// Check each package
	for _, pkg := range pkgList {
		// Skip packages that have compile errors (DepsErrors)
		// But we still want to check them if possible

		// Print "checking" in verbose mode
		pkgName := pkg.ImportPath
		if pkg.ForTest != "" {
			// This is a test variant like "testpkg [testpkg.test]"
			// Extract the test binary name
			// go list -test produces package with ForTest field set
		}
		if *verbose {
			fmt.Fprintf(os.Stderr, "checking %s\n", pkgName)
		}

		// Load and check the package
		cp, err := loadAndCheck(pkg, cfg, nil)
		if err != nil {
			// Print error but continue
			continue
		}

		pkgErrors := chkr.checkPackage(cp)
		for _, e := range pkgErrors {
			key := fmt.Sprintf("%s:%d:%d", e.pos.Filename, e.pos.Line, e.pos.Column)
			if !seenPos[key] {
				seenPos[key] = true
				allErrors = append(allErrors, e)
			}
		}
	}

	// Sort errors
	sort.Slice(allErrors, func(i, j int) bool {
		ei, ej := allErrors[i], allErrors[j]
		if ei.pos.Filename != ej.pos.Filename {
			return ei.pos.Filename < ej.pos.Filename
		}
		if ei.pos.Line != ej.pos.Line {
			return ei.pos.Line < ej.pos.Line
		}
		return ei.pos.Column < ej.pos.Column
	})

	// Print errors
	for _, e := range allErrors {
		filename := e.pos.Filename
		if !*abspath {
			wd, _ := os.Getwd()
			if rel, err := filepath.Rel(wd, filename); err == nil {
				filename = rel
			}
		}

		if *verbose && e.fn != "" {
			fmt.Printf("%s:%d:%d:\t%s\t%s\n", filename, e.pos.Line, e.pos.Column, e.fn, e.line)
		} else {
			fmt.Printf("%s:%d:%d:\t%s\n", filename, e.pos.Line, e.pos.Column, e.line)
		}
	}

	if len(allErrors) > 0 {
		os.Exit(1)
	}
}
