package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
)

var errorLineRe = regexp.MustCompile(`^(\./[^:]+):(\d+):(\d+): (.*)$`)

func checkBuildErrors(pkgDir, pkgImportPath string) string {
	cmd := exec.Command("go", "build", "-o", os.DevNull, ".")
	cmd.Dir = pkgDir
	out, err := cmd.CombinedOutput()
	if err != nil {
		stderr := string(out)
		return formatBuildError(stderr, pkgDir)
	}
	return ""
}

func formatBuildError(buildStderr, pkgDir string) string {
	lines := strings.Split(strings.TrimRight(buildStderr, "\n"), "\n")

	var absErrors []string
	for _, line := range lines {
		if strings.HasPrefix(line, "#") {
			continue
		}
		m := errorLineRe.FindStringSubmatch(line)
		if m != nil {
			relPath := m[1]
			lineNum := m[2]
			colNum := m[3]
			msg := m[4]
			absPath := filepath.Join(pkgDir, relPath[2:])
			absErrors = append(absErrors, fmt.Sprintf("%s:%s:%s: %s", absPath, lineNum, colNum, msg))
		}
	}

	stripped := strings.TrimRight(buildStderr, "\n")
	result := stripped
	if len(absErrors) > 0 {
		result += " " + strings.Join(absErrors, " ")
	}
	return result
}

